use bhoo::android_calendar::CalendarDate as D;
use bhoo::android_date_spinner::{DateSpinnerField as F,DateSpinnerState};
fn d(y:i32,m:u8,day:u8)->D{D::new(y,m,day).unwrap()}
#[test] fn day_wraps_across_months_and_years(){let mut s=DateSpinnerState::new(d(2020,1,1),d(2035,12,31),d(2024,12,31)).unwrap();assert!(s.set_field(F::Day,1).unwrap());assert_eq!(s.date(),d(2025,1,1));assert!(s.set_field(F::Day,31).unwrap());assert_eq!(s.date(),d(2024,12,31));}
#[test] fn month_wrap_and_month_length_are_correct(){let mut s=DateSpinnerState::new(d(2020,1,1),d(2035,12,31),d(2024,1,31)).unwrap();s.set_field(F::Month,2).unwrap();assert_eq!(s.date(),d(2024,2,29));s.set_field(F::Month,1).unwrap();s.set_field(F::Month,12).unwrap();assert_eq!(s.date(),d(2023,12,29));}
#[test] fn year_change_matches_lenient_spinner_delegate(){let mut s=DateSpinnerState::new(d(2020,1,1),d(2035,12,31),d(2024,2,29)).unwrap();s.set_field(F::Year,2023).unwrap();assert_eq!(s.date(),d(2023,3,1));}
#[test] fn bounds_clamp_and_endpoint_ranges_disable_wrapping(){let mut s=DateSpinnerState::new(d(2024,2,15),d(2024,5,10),d(2024,2,16)).unwrap();s.set_field(F::Day,1).unwrap();assert_eq!(s.date(),d(2024,2,15));let r=s.range(F::Day);assert_eq!((r.min,r.value,r.wrap_preferred),(15,15,false));assert!(s.set_field(F::Day,14).is_err());s.set_field(F::Month,5).unwrap();assert_eq!(s.date(),d(2024,5,10));assert!(s.set_field(F::Day,31).is_err());let r=s.range(F::Month);assert_eq!((r.max,r.value,r.wrap_preferred),(5,5,false));}
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_date_picker_spinner.rs"));}
#[test] fn xml_day_wheel_carries_and_editor_commit_updates_date(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.date_spinners.insert("date_spinner".into(),DateSpinnerState::new(d(2020,1,1),d(2035,12,31),d(2024,1,31)).unwrap());let b=Rect{x:0.,y:0.,width:360.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut a=None;ui.frame(input,b,0.,|f|a=fixture::LAYOUT.render(f,b,s));a};draw(&mut ui,&mut s,Input::default());let point=Some([180.,120.]);draw(&mut ui,&mut s,Input{pointer:point,pressed:true,time:1.,..Input::default()});assert_eq!(draw(&mut ui,&mut s,Input{pointer:point,released:true,time:1.01,..Input::default()}),Some("date_spinner"));assert_eq!(s.date_spinners["date_spinner"].date(),d(2024,2,1));draw(&mut ui,&mut s,Input{time:1.5,..Input::default()});s.number_picker_editing.insert("date_spinner:D".into());s.text.insert("date_spinner:D".into(),"15".into());assert!(s.end_number_picker_edit("date_spinner:D",true));assert_eq!(draw(&mut ui,&mut s,Input{time:1.6,..Input::default()}),Some("date_spinner"));assert_eq!(s.date_spinners["date_spinner"].date(),d(2024,2,15));}
mod combined {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_date_picker_combined.rs"));}
#[test] fn xml_calendar_and_wheels_remain_synchronized(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.date_spinners.insert("date_combined".into(),DateSpinnerState::new(d(2020,1,1),d(2035,12,31),d(2024,2,1)).unwrap());let b=Rect{x:0.,y:0.,width:700.,height:340.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut a=None;ui.frame(input,b,0.,|f|a=combined::LAYOUT.render(f,b,s));a};draw(&mut ui,&mut s,Input::default());let point=Some([164.,218.]);draw(&mut ui,&mut s,Input{pointer:point,pressed:true,time:1.,..Input::default()});assert_eq!(draw(&mut ui,&mut s,Input{pointer:point,released:true,time:1.01,..Input::default()}),Some("date_combined"));assert_eq!(s.date_spinners["date_combined"].date(),d(2024,2,2));assert_eq!(s.calendars["date_combined"].selected(),d(2024,2,2));draw(&mut ui,&mut s,Input{time:1.3,..Input::default()});let target=ui.semantics().iter().find(|n|n.label.as_ref()=="15").unwrap().bounds;let point=Some([target.x+target.width/2.,target.y+target.height/2.]);draw(&mut ui,&mut s,Input{pointer:point,pressed:true,time:1.4,..Input::default()});assert_eq!(draw(&mut ui,&mut s,Input{pointer:point,released:true,time:1.41,..Input::default()}),Some("date_combined"));assert_eq!(s.date_spinners["date_combined"].date(),d(2024,2,15));draw(&mut ui,&mut s,Input{time:1.5,..Input::default()});assert_eq!(s.number_pickers["date_combined:D"].value(),15);}
#[test] fn both_visibility_flags_false_keeps_wheels(){use bhoo::*;use bhoo::android_xml::RelativeRule;static RULES:[RelativeRule;3]=[RelativeRule{kind:102,anchor:"spinner"},RelativeRule{kind:103,anchor:"false"},RelativeRule{kind:104,anchor:"false"}];let mut node=combined::LAYOUT.children[0];node.relative_rules=&RULES;let node=Box::leak(Box::new(node));let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();let b=Rect{x:0.,y:0.,width:350.,height:340.};ui.frame(Input::default(),b,0.,|f|{node.render(f,b,&mut s);});assert_eq!(ui.semantics().iter().filter(|n|n.label.as_ref()=="Increase").count(),3);assert!(!ui.semantics().iter().any(|n|n.label.as_ref()=="Next month"));}
